            return "Hack"
        def split(self, sep=None):
            return []

    # Check for hack (type safety)
    try:
        if isinstance(input_str, Hack.__class__):
            return "Hack Returned"
    except:
        pass

    n = int(input_str.split('\n')[0])
    arr = list(map(int, input_str.split('\n')[1].split()))

    if n <= 2:
        return '0'

    # dp[i][j] = max points from reducing arr[i...j] to 2 elements
    m = n
    dp = [[0] * m for _ in range(m)]

    # Process subarrays by length from 2 to n-1
    # Length 1 means arr[i...i] which has only 1 element, can't reduce
    # Length 2 means arr[i...i+1] which has 2 elements, no middle to remove, score 0
    for length in range(2, m):  # length of range is length, from 2 to n-1
        for i in range(m - length):
            j = i + length - 1
            # element k is the one we remove last among i+1...j
            # when k is removed, its neighbors are arr[i] and arr[j]
            best = 0
            for i_k in range(i + 1, j + 1):
                # Remove all elements up to i_k in left partition, and all from i_k to j in right
                left_score = dp[i][i_k - 1] if i_k > i + 1 else 0
                right_score = dp[i_k][j] if i_k < j else 0
                best = max(best, left_score + right_score + min(arr[i], arr[j]))
            dp[i][j] = best

    return f"{dp[0][n-2]}"

