def solution(input_str):
    lines = input_str.strip().split('\n')
    a = list(map(int, lines[0].split()))
    b = list(map(int, lines[1].split()))

    # Check multisets match
    if sorted(a) != sorted(b):
        return "-1\n"

    def gcd_algo(x, y):
        while y:
            x, y = y, x % y
        return x

    def pairwise_gcd(lst):
        g = 0
        n = len(lst)
        for i in range(n):
            for j in range(i + 1, n):
                d = abs(lst[j] - lst[i])
                g = gcd_algo(g, d)
        return g

    # Check GCD invariant
    if pairwise_gcd(a) != pairwise_gcd(b):
        return "-1\n"

    # If all positions same initially but different in target
    if len(set(a)) == 1 and len(set(b)) > 1:
        return "-1\n"

    start_state = tuple(sorted(a))
    target_state = tuple(sorted(b))

    if start_state == target_state:
        return "0\n"

    # BFS search with operation limit
    queue = deque([(start_state, [])])
    visited = {start_state}
    parent = {start_state: None}

    while queue:
        state, path = queue.popleft()

        if len(path) >= 1000:
            continue

        stones = list(state)

