        [(0,0), (0,1), (0,2), (1,1), (2,1)],  # Top bar
        [(1,0), (1,1), (1,2), (0,1), (2,1)],  # Rotated top 1
        [(2,0), (2,1), (2,2), (1,1), (0,1)],  # Rotated top 2
        [(0,2), (1,2), (2,2), (1,1), (0,1)],   # Rotated top 3
    ]

    def dx(shape, r, c):
        """Check if each cell (r, c) + (dr, dc) is in bounds"""
        for dr, dc in shape:
            if r + dr < 0 or r + dr >= n or c + dc < 0 or c + dc >= m:
                return False
        return True

    def can_place(board, shape, r, c):
        """Check if shape can be placed at (r, c) - all 5 cells must be free"""
        for dr, dc in shape:
            if board[r + dr][c + dc]:
                return False
        return True

    def place_shape(board, shape, r, c, piece_id):
        """Place shape on board"""
        for dr, dc in shape:
            board[r + dr][c + dc] = piece_id

