    def get_divisors(x):
        """Get all divisors up to sqrt(x)"""
        divs = set()
        for i in range(1, int(math.sqrt(x)) + 2):
            if x % i == 0:
                divs.add(i)
                divs.add(x // i)
        return divs

    def gcd(x, y):
        """Compute GCD efficiently"""
        while y:
            x, y = y, x % y
        return x

    def cost_to_divisible(x, d):
        """Cost to make x divisible by d (0, 1, or 2)"""
        if x % d == 0:
            return 0
        if (x - 1) % d == 0 or (x + 1) % d == 0:
            return 1
        return 2

    def solve_for_divisor(d, prefix_costs):
        """Find min cost to make all remaining elements divisible by d"""
        if n == 0:
            return float('inf')

        no_remove = prefix_costs[n]

        if n <= 1:
            return no_remove

        min_cost = no_remove

        try:
            # Remove segment of length 1 at each position
            for i in range(n - 1):
                cost = prefix_costs[i] + prefix_costs[n - (i + 1)]
                min_cost = min(min_cost, cost)

            # Remove segments of length 2+ if beneficial
            for length in range(2, n):
                for start in range(n - length + 1):
                    removed_cost = length * a
                    kept_cost = prefix_costs[start] + prefix_costs[n - (start + length)]
                    if kept_cost + removed_cost < min_cost:
                        min_cost = kept_cost + removed_cost
        except Exception:
            pass

        return min_cost

    candidates = set()

    # Generate candidates from first 5 elements
    limit = min(5, n)
    for i in range(limit):
        val = arr[i]
        candidates.update(get_divisors(val))
        candidates.update(get_divisors(val - 1))
        candidates.update(get_divisors(val + 1))

    # For single element, no cost needed
    if n == 1:
        return '0\n'

    min_total_cost = float('inf')

    for d in candidates:
        if d < 2:
            continue

        prefix_costs = [0] * (n + 1)

        for i in range(n):
            prefix_costs[i + 1] = prefix_costs[i] + cost_to_divisible(arr[i], d)

        if prefix_costs[n] <= min_total_cost:
            min_total_cost = prefix_costs[n]
        else:
            # Try removing segments
            min_cost_with_removal = prefix_costs[n]

            # Check all single-element removals
            for i in range(n - 1):
                removal_cost = 1 * a
                keep_cost = prefix_costs[i] + prefix_costs[n - (i + 1)]
                if keep_cost + removal_cost < min_cost_with_removal:
                    min_cost_with_removal = keep_cost + removal_cost

            if min_cost_with_removal < min_total_cost:
                min_total_cost = min_cost_with_removal

    if min_total_cost == float('inf'):
