            a.append((101 * last_val - 10007) % MOD)

        def gcd(x, y):
            while y:
                x, y = y, x % y
            return x

        def count_divisors(n):
            if n == 0:
                return 0
            count = 0
            for i in range(1, int(n**0.5) + 1):
                if n % i == 0:
                    count += 1
                    if i * i != n:
                        count += 1
            return count

        def matrix_multiply(A, B, n, mod):
            C = [[0] * n for _ in range(n)]
            for i in range(n):
                for k in range(n):
                    if A[i][k] == 0:
                        continue
                    for j in range(n):
                        if B[k][j] != 0:
                            C[i][j] = (C[i][j] + A[i][k] * B[k][j]) % mod
            return C

        def matrix_power(A, p, n, mod):
            result = [[1 if i == j else 0 for j in range(n)] for i in range(n)]
            base = [row[:] for row in A]
            while p > 0:
                if p & 1:
                    result = matrix_multiply(result, base, n, mod)
                base = matrix_multiply(base, base, n, mod)
                p >>= 1
            return result

        # Build transition matrix
        # adj[i][j] = ways to go from island j to island i
        adj = [[0] * n for _ in range(n)]

        for i in range(n):
            for j in range(n):
                if i == j:
                    # Stay at island (i+1): all divisors + 1 for staying
                    adj[i][j] = count_divisors(i + 1) + 1
                else:
                    # Move from island (j+1) to island (i+1)
                    u = i + 1
                    v = j + 1
                    g = gcd(u, v)
                    # 2 * number of common divisors
                    adj[i][j] = 2 * count_divisors(g)

        # Compute M^t
        Mt = matrix_power(adj, t, n, MOD)

        # Final state: sum over starting positions
        initial = [val for val in a]

        final = [0] * n
        for i in range(n):
            val = 0
            for j in range(n):
                val = (val + Mt[i][j] * initial[j]) % MOD
            final[i] = val

        # XOR sum
        ans = 0
        for v in final:
            ans ^= v

        return str(ans) + "\n"

    except Exception:
        return ""

