    if k == 1:
        return str(n % MOD)

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dp(pos, steps_left, visited_mask):
        """
        pos: current planet (can use any position)
        steps_left: how many more planets we need to visit
        visited_mask: bitmask where bit i is set if planet (i+1) was visited
        """
        if steps_left == 0:
            return 1

        result = 0
        limit = min(n, pos + m)

        for next_pos in range(1, limit + 1):
            # If next_pos hasn't been visited
            if not (visited_mask & (1 << (next_pos - 1))):
                result = (result + dp(next_pos, steps_left - 1, visited_mask | (1 << (next_pos - 1)))) % MOD

        return result

    # Count all sequences starting from each possible starting planet
    total = 0
    for start_pos in range(1, n + 1):
        total = (total + dp(start_pos, k - 1, 0)) % MOD

    return str(total)

