    n = int(s.strip())

    if n == 0:
        return "0\n"

    # Use memoization with BFS
    # For very large numbers, the key insight is:
    # When we have a number, we should greedily subtract the largest digit
    # This allows us to get close to the next round of digits faster

    memo = {}

    def get_min_ops(num):
        if num == 0:
            return 0
        if num in memo:
            return memo[num]

        digits = set(int(d) for d in str(num))

        best = float('inf')
        for d in digits:
            result = get_min_ops(num - d)
            if result != -1:
                best = min(best, result + 1)

        memo[num] = best if best != float('inf') else -1
        return best

    # For numbers up to 10^18, we need to be efficient
    # Let's use iterative DFS with limit
    from collections import deque

    # BFS from n
    queue = deque([(n, 0)])
    visited = {n}

    while queue:
        current, steps = queue.popleft()

        if current == 0:
            return str(steps) + "\n"

        digits = sorted(set(int(d) for d in str(current)))

        for d in digits:  # Process smaller digits first for better cache
            new_num = current - d
            if new_num >= 0 and new_num not in visited:
                visited.add(new_num)
                queue.append((new_num, steps + 1))

    return "-1\n"

